import pandas as pd


def _get_input(inputs, name):
    if name in inputs:
        return inputs[name]
    lname = name.lower()
    for k in inputs:
        if k.lower() == lname:
            return inputs[k]
    raise KeyError(name)


def _segments_differ(s1, s2):
    n1 = pd.isna(s1)
    n2 = pd.isna(s2)
    if n1 and n2:
        return False
    if n1 or n2:
        return True
    return s1 != s2


def run(inputs: dict) -> dict:
    dim = _get_input(inputs, 'DIM_CUSTOMER').copy()
    stg = _get_input(inputs, 'STG_CUSTOMER').copy()
    fact = _get_input(inputs, 'FACT_TXN').copy()

    # Normalize dtypes defensively
    if len(dim) > 0:
        dim['customer_sk'] = dim['customer_sk'].astype(int)
        dim['customer_id'] = dim['customer_id'].astype(int)
        dim['is_current'] = dim['is_current'].astype(int)

    max_sk = dim['customer_sk'].max() if len(dim) > 0 else 0
    if pd.isna(max_sk):
        max_sk = 0

    # Map of current row per customer_id (assume at most one current row per customer)
    current = dim[dim['is_current'] == 1]
    current_map = {}
    for _, r in current.iterrows():
        current_map[r['customer_id']] = r['segment']

    stg_sorted = stg.sort_values('customer_id', kind='mergesort').reset_index(drop=True)

    creates = []  # (customer_id, segment, update_date)
    expire_updates = {}  # customer_id -> update_date

    for _, row in stg_sorted.iterrows():
        cid = row['customer_id']
        seg = row['segment']
        upd_date = row['update_date']

        if cid in current_map:
            cur_seg = current_map[cid]
            if _segments_differ(seg, cur_seg):
                creates.append((cid, seg, upd_date))
                expire_updates[cid] = upd_date
        else:
            creates.append((cid, seg, upd_date))

    # Order creates by customer_id for ROW_NUMBER() OVER (ORDER BY customer_id)
    creates_sorted = sorted(creates, key=lambda x: x[0])

    new_rows = []
    for i, (cid, seg, upd_date) in enumerate(creates_sorted, start=1):
        new_sk = max_sk + i
        new_rows.append({
            'customer_sk': new_sk,
            'customer_id': cid,
            'segment': seg,
            'eff_start_date': upd_date,
            'eff_end_date': pd.NaT,
            'is_current': 1
        })

    # Expire prior current rows that were superseded
    dim_updated = dim.copy()
    for cid, upd_date in expire_updates.items():
        mask = (dim_updated['customer_id'] == cid) & (dim_updated['is_current'] == 1)
        dim_updated.loc[mask, 'eff_end_date'] = upd_date
        dim_updated.loc[mask, 'is_current'] = 0

    new_df = pd.DataFrame(new_rows, columns=[
        'customer_sk', 'customer_id', 'segment',
        'eff_start_date', 'eff_end_date', 'is_current'
    ])

    if len(dim_updated) == 0:
        dim_out = new_df
    elif len(new_df) == 0:
        dim_out = dim_updated
    else:
        dim_out = pd.concat([dim_updated, new_df], ignore_index=True)

    dim_out = dim_out[['customer_sk', 'customer_id', 'segment',
                        'eff_start_date', 'eff_end_date', 'is_current']].reset_index(drop=True)

    # Step 2: key facts against the updated dimension
    # Build lookup grouped by customer_id for efficiency
    dim_by_cust = {}
    for _, r in dim_out.iterrows():
        dim_by_cust.setdefault(r['customer_id'], []).append(r)

    def find_sk(cid, txn_date):
        rows = dim_by_cust.get(cid)
        if not rows:
            return -1
        for r in rows:
            start = r['eff_start_date']
            end = r['eff_end_date']
            if pd.isna(start):
                continue
            if start <= txn_date and (pd.isna(end) or txn_date < end):
                return r['customer_sk']
        return -1

    fact_out = fact.copy()
    if len(fact_out) > 0:
        fact_out['customer_sk'] = fact_out.apply(
            lambda r: find_sk(r['customer_id'], r['txn_date']), axis=1
        )
    else:
        fact_out['customer_sk'] = pd.Series(dtype=int)

    fact_txn_keyed = fact_out[['txn_id', 'customer_sk', 'amount']].reset_index(drop=True)

    return {
        'dim_customer_out': dim_out,
        'fact_txn_keyed': fact_txn_keyed
    }
